use std::collections::HashMap;
use std::path::PathBuf;

use zbobr_utility::config_struct;

use crate::task::{Model, Role, Tool};

/// Auto-generated by #[config_struct] for every config struct.
pub trait Config: Sized {
    type Toml: Default + for<'de> serde::Deserialize<'de>;
    type Args: clap::Args + zbobr_utility::PrefixedArgs + Default + Clone;
    fn build(toml: Option<Self::Toml>, args: Self::Args, config_dir: &std::path::Path) -> Self;
}

/// A single stage in the configurable pipeline.
///
/// Parsed from `[[stages]]` TOML array. NOT a `#[config_struct]` — no CLI override.
#[derive(Clone, Debug, serde::Deserialize, serde::Serialize)]
pub struct StageDefinition {
    pub name: String,
    pub role: Role,
    #[serde(default)]
    pub model: Option<Model>,
    #[serde(default)]
    pub tool: Option<Tool>,
    #[serde(default)]
    pub main_prompt: Option<PathBuf>,
    #[serde(default)]
    pub additional_prompts: Vec<PathBuf>,
    /// MCP operation name (or "default") → signal string (go_X, call_X, return).
    #[serde(default)]
    pub transitions: HashMap<String, String>,
    #[serde(default)]
    pub is_start: bool,
    pub mode: String,
}

/// Pipeline configuration: the set of all stage definitions.
#[derive(Clone, Debug, serde::Deserialize, serde::Serialize)]
pub struct PipelineConfig {
    pub stages: Vec<StageDefinition>,
}

impl PipelineConfig {
    /// Look up a stage by name within a mode.
    pub fn stage_by_name(&self, mode: &str, name: &str) -> Option<&StageDefinition> {
        self.stages
            .iter()
            .find(|s| s.mode == mode && s.name == name)
    }

    /// Get the start stage for a mode.
    pub fn start_stage_for_mode(&self, mode: &str) -> Option<&StageDefinition> {
        self.stages
            .iter()
            .find(|s| s.mode == mode && s.is_start)
    }

    /// Get all stages for a mode.
    pub fn stages_for_mode(&self, mode: &str) -> Vec<&StageDefinition> {
        self.stages.iter().filter(|s| s.mode == mode).collect()
    }

    /// The default mode is the one whose start stage has `is_start == true`
    /// and whose mode name appears first.
    pub fn default_mode(&self) -> Option<&str> {
        self.stages
            .iter()
            .find(|s| s.is_start)
            .map(|s| s.mode.as_str())
    }

    /// Find the first stage with a given role (across all modes, preferring default mode).
    pub fn find_stage_by_role(&self, role: Role) -> Option<&StageDefinition> {
        // Prefer stages in the default mode
        if let Some(default_mode) = self.default_mode() {
            if let Some(s) = self
                .stages
                .iter()
                .find(|s| s.mode == default_mode && s.role == role)
            {
                return Some(s);
            }
        }
        self.stages.iter().find(|s| s.role == role)
    }

    /// All distinct mode names.
    pub fn modes(&self) -> Vec<&str> {
        let mut modes: Vec<&str> = self.stages.iter().map(|s| s.mode.as_str()).collect();
        modes.sort();
        modes.dedup();
        modes
    }

    /// Validate pipeline configuration.
    pub fn validate(&self) -> anyhow::Result<()> {
        let modes = self.modes();

        // Each mode must have exactly one is_start stage
        for mode in &modes {
            let start_count = self
                .stages
                .iter()
                .filter(|s| s.mode == *mode && s.is_start)
                .count();
            if start_count == 0 {
                anyhow::bail!("Mode '{}' has no start stage (is_start = true)", mode);
            }
            if start_count > 1 {
                anyhow::bail!("Mode '{}' has {} start stages, expected 1", mode, start_count);
            }
        }

        // Validate transition targets: go_{stage} must reference a stage in the same mode
        for stage in &self.stages {
            for (op, signal) in &stage.transitions {
                if let Some(target) = signal.strip_prefix("go_") {
                    if self.stage_by_name(&stage.mode, target).is_none() {
                        anyhow::bail!(
                            "Stage '{}/{}' transition '{}' → 'go_{}' references unknown stage '{}' in mode '{}'",
                            stage.mode, stage.name, op, target, target, stage.mode
                        );
                    }
                } else if let Some(target_mode) = signal.strip_prefix("call_") {
                    if !modes.contains(&target_mode) {
                        anyhow::bail!(
                            "Stage '{}/{}' transition '{}' → 'call_{}' references unknown mode '{}'",
                            stage.mode, stage.name, op, target_mode, target_mode
                        );
                    }
                } else if signal != "return" {
                    anyhow::bail!(
                        "Stage '{}/{}' transition '{}' → '{}' is invalid (expected go_X, call_X, or return)",
                        stage.mode, stage.name, op, signal
                    );
                }
            }
        }

        // No duplicate stage names within a mode
        for mode in &modes {
            let mode_stages = self.stages_for_mode(mode);
            let mut names: Vec<&str> = mode_stages.iter().map(|s| s.name.as_str()).collect();
            names.sort();
            for window in names.windows(2) {
                if window[0] == window[1] {
                    anyhow::bail!(
                        "Duplicate stage name '{}' in mode '{}'",
                        window[0], mode
                    );
                }
            }
        }

        Ok(())
    }
}

/// Configuration for the zbobr dispatcher.
#[derive(Clone)]
#[config_struct]
pub struct ZbobrDispatcherConfig {
    /// Workspaces directory; each task gets a separate subdirectory.
    #[config(path)]
    pub workspaces: std::path::PathBuf,
    /// Base port for the MCP server; zbobr scans upward from this port to find
    /// an available one.
    #[arg(default_value = "3000")]
    pub base_port: u16,
    /// Read-only GitHub token passed as GH_TOKEN/GITHUB_TOKEN to agent processes.
    /// This is a security boundary: it limits what agents can do on GitHub — agents must
    /// not have write access so that erroneous or misbehaving agents cannot modify remote
    /// repositories. Use a fine-grained token with read-only scopes (or no scopes at all
    /// for fully offline/mcp-tester runs). Defaults to "not-configured" when omitted.
    pub agent_github_token: String,
    /// CLI tool to use as a global default. Individual stages may override this.
    pub tool: Tool,
    /// Global AI model to use when a stage does not specify an override.
    pub model: Model,
    /// Prefix for work branches (default: "zbobr_fix").
    pub work_branch_prefix: String,
    /// Default destination repository pre-populated into task parameters before the
    /// preparator agent runs (e.g. "owner/repo" or a full git URL). The preparator
    /// may still override this value.
    pub default_destination_repository: Option<String>,
    /// Default destination branch pre-populated into task parameters before the
    /// preparator agent runs (e.g. "main"). The preparator may still override this.
    pub default_destination_branch: Option<String>,
    /// Mode to call when a merge conflict is detected.
    pub on_conflict: Option<String>,
}

impl Default for ZbobrDispatcherConfig {
    fn default() -> Self {
        Self {
            workspaces: std::path::PathBuf::from("./workspaces"),
            base_port: 3000,
            agent_github_token: "not-configured".to_string(),
            tool: Tool::default(),
            model: Model::default(),
            work_branch_prefix: "zbobr_fix".to_string(),
            default_destination_repository: None,
            default_destination_branch: None,
            on_conflict: None,
        }
    }
}

impl ZbobrDispatcherConfig {
    /// Load configuration from environment variables only (backward compat).
    pub fn from_env() -> anyhow::Result<Self> {
        let cwd = std::env::current_dir()
            .map_err(|e| anyhow::anyhow!("Cannot get current directory: {e}"))?;
        Ok(<Self as Config>::build(
            None,
            ZbobrDispatcherArgs::default(),
            &cwd,
        ))
    }

    /// Validate that global tool/model are compatible.
    pub fn validate(&self) -> anyhow::Result<()> {
        if self.model.model_name_for_tool(self.tool).is_none() {
            anyhow::bail!(
                "Global model {:?} is not supported by global tool {:?}",
                self.model,
                self.tool
            );
        }
        Ok(())
    }

    /// Determine which tool to use for a stage, falling back to global default.
    pub fn tool_for_stage(&self, stage_def: &StageDefinition) -> Tool {
        stage_def.tool.unwrap_or(self.tool)
    }

    /// Determine which model to use for a stage, falling back to global default.
    pub fn model_for_stage(&self, stage_def: &StageDefinition) -> Model {
        stage_def.model.clone().unwrap_or(self.model.clone())
    }
}
